program = '''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    colored = {(r, c) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 1)}
    components = []
    while colored:
        seed = colored.pop()
        component = {seed}
        stack = [seed]
        while stack:
            r, c = stack.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    q = (r + dr, c + dc)
                    if q in colored:
                        colored.remove(q)
                        component.add(q)
                        stack.append(q)
        components.append(component)
    out = [row[:] for row in grid]
    for component in components:
        center_color = Counter(grid[r][c] for r, c in component).most_common(1)[0][0]
        central = {(r, c) for r, c in component if grid[r][c] == center_color}
        rs = [r for r, c in central]
        cs = [c for r, c in central]
        minr, maxr, minc, maxc = min(rs), max(rs), min(cs), max(cs)
        cr, cc = (minr + maxr) // 2, (minc + maxc) // 2
        starts = [
            (minr, cc, -1, -1), (minr, cc, -1, 1),
            (cr, maxc, -1, 1), (cr, maxc, 1, 1),
            (maxr, cc, 1, 1), (maxr, cc, 1, -1),
            (cr, minc, 1, -1), (cr, minc, -1, -1),
        ]
        painted = set()
        for r, c, dr, dc in starts:
            rr, cc2 = r + dr, c + dc
            ray = []
            color = None
            while 0 <= rr < h and 0 <= cc2 < w:
                ray.append((rr, cc2))
                if color is None and grid[rr][cc2] not in (0, 1, center_color):
                    color = grid[rr][cc2]
                rr += dr
                cc2 += dc
            if color is not None:
                for q in ray:
                    out[q[0]][q[1]] = color
                    painted.add(q)
        # Clipped input rays can leave a one-cell spur on their outer crop row.
        exterior = component - central
        if exterior:
            outer_r = min(r for r, c in exterior)
            for r, c in exterior:
                if r == outer_r and (r, c) not in painted:
                    out[r][c] = 1 if (r + c) % 2 == 0 else 0
    return out
'''
